<script setup>
import AppSelect from '../../shared/components/AppSelect.vue';
import TablePanel from '../../shared/components/TablePanel.vue';

import {computed,inject,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import { accountTypes, financeKey, money } from './finance-model.js';
import {accountParameters} from './finance-api.js';
import FinanceDialog from './FinanceDialog.vue';
const vm=inject(financeKey), emit=defineEmits(['movements']), size=ref(10), page=ref(1), detail=ref(null);
const resource=vm.resource('accounts'),shown=computed(()=>resource.state.rows),pages=computed(()=>resource.state.meta.last_page||1);
let timer;
async function load({fresh=false,preserve=false}={}){if(!preserve)detail.value=null;await resource.load({...accountParameters(vm.filters),per_page:size.value,page:page.value},{fresh});vm.rememberAccounts(resource.state.rows);await vm.loadWallets(undefined,resource.state.rows.map(row=>row.id),{fresh});}
const unregisterRefresh=vm.registerRefresh?.(()=>load({fresh:true,preserve:true}));onBeforeUnmount(()=>unregisterRefresh?.());
watch(size,()=>{clearTimeout(timer);page.value=1;timer=setTimeout(load,300);});
watch(page,load);watch(vm.filters,()=>{page.value=1;load();},{deep:true});watch(()=>vm.balanceGeneration.value,()=>{void vm.loadWallets(undefined,shown.value.map(row=>row.id));});onMounted(load);onBeforeUnmount(()=>clearTimeout(timer));
function movements() { const id=detail.value.id; detail.value=null; emit('movements',id); }
</script>
<template><section class="card wallet-accounts-table" data-no-pagination><div class="cardhead"><h3>الحسابات والأرصدة</h3></div><div class="wallet-account-tools"><label>عرض<AppSelect v-model.number="size" aria-label="عدد الحسابات في الصفحة"><option v-for="number in [10,25,50,100]" :key="number" :value="number">{{number}}</option></AppSelect></label></div><p class="caption">عدد الحسابات المطابقة: {{resource.state.loading ? "—" : resource.state.meta.total}}</p><p v-if="resource.state.error" class="notice warn" role="alert">{{resource.state.error}}</p><TablePanel :start="(page-1)*size+1" class="tablewrap"><table><thead><tr><th>الحساب</th><th>النوع</th><th>تابع إلى</th><th>الرصيد المتاح</th><th>الإجراء</th></tr></thead><tbody><tr v-for="row in shown" :key="row.id"><td>{{row.name}}</td><td>{{accountTypes[row.type] || row.type}}</td><td>{{row.parent_name || (row.parent_id?vm.name(row.parent_id):'—')}}</td><td>{{money(vm.walletAmount(row.id,vm.service.value,vm.currency.value))}} {{vm.currencyLabel(vm.currency.value)}}</td><td><button class="btn small" @click="detail=row">عرض التفاصيل</button></td></tr><tr v-if="!resource.state.meta.total && !resource.state.loading"><td colspan="5" class="empty">لا توجد حسابات مطابقة</td></tr></tbody></table></TablePanel><div class="table-pagination-footer"><button class="btn small" :disabled="page<=1" @click="page--">السابق</button><span>الصفحة {{page}} من {{pages}}</span><button class="btn small" :disabled="page>=pages" @click="page++">التالي</button></div></section>
  <FinanceDialog :open="!!detail" :title="detail?.name || 'تفاصيل الحساب'" @close="detail=null"><template v-if="detail"><dl class="account-fields"><div><dt>النوع</dt><dd>{{accountTypes[detail.type] || detail.type}}</dd></div><div><dt>تابع إلى</dt><dd>{{detail.parent_id?vm.name(detail.parent_id):'—'}}</dd></div><div><dt>المحافظة</dt><dd>{{detail.city || detail.governorate_name || '—'}}</dd></div><div><dt>الحالة</dt><dd>{{detail.status==='active'?'مفعّل':detail.status?'معطّل':'—'}}</dd></div><div><dt>الرصيد الحالي</dt><dd>{{money(vm.walletAmount(detail.id,vm.service.value,vm.currency.value,'balance'))}} {{vm.currencyLabel(vm.currency.value)}}</dd></div><div><dt>الرصيد المتاح</dt><dd>{{money(vm.walletAmount(detail.id,vm.service.value,vm.currency.value))}} {{vm.currencyLabel(vm.currency.value)}}</dd></div></dl><div class="formfoot"><button class="btn" @click="detail=null">إغلاق</button><button v-if="vm.can('ledger.view')" class="btn primary" @click="movements">عرض حركاته</button></div></template></FinanceDialog>
</template>
